let phase='intro',cameraMode='card',openAmount=0,pullAmount=0,drag=null,dialogueIndex=0,last=performance.now(),typing=false,typeTimer=null,chainSwing=0,lastRattle=0,audioContext=null,roomLit=false,contentReveal=0,revealReady=false,guestReveal=0,decorationReveal=0,balloonSpread=0,shakeEnergy=0,lastMotion=0,candleFound=false,micStream=null,micAnalyser=null,micSamples=null,blowFrames=0;const lines=['Está muy oscuro aquí… apenas puedo ver algo.','Debe haber alguna forma de alumbrar este cuarto.','Espera… ¿ves ese cordón? Tal vez deberías jalarlo.','¡Eso está mucho mejor! Espera… ¿qué es esa caja?','¡Un pastel! Sabía que esta caja escondía algo especial.','Un momento… ¿escuchaste ese ruido detrás de nosotros?','Ya están todos listos para el pastel… pero aguarda. ¡Falta algo! ¡La vela!','¡Miaui, miaui, miaui!','¿Olvidaron la vela dentro de algún globo? Ayúdame a encontrarla.','Primero tenemos que dispersarlos. ¡Agita tu teléfono!','¡Ahí está! Encontramos la vela.','Ahora sí, es hora de continuar. Enciende la vela.','Es momento de pedir un deseo…','Y, de repente… todos guardaron silencio.','Por un instante, nadie se movió. El cuarto entero pareció contener la respiración.','Entonces, desde algún rincón, comenzó a sonar una canción…'];
lines.push('No quiero alarmarte, pero mi experiencia como narrador indica que los cuartos oscuros nunca vienen con instrucciones… ni con servicio al cliente.','Aunque, pensándolo bien, unos ojos de gato verían perfectamente aquí. Qué conveniente que todavía no haya ninguno cerca.','Mucho mejor. Y oficialmente confirmo que no era un cuarto embrujado; sólo necesitaba pagar su recibo de luz.','Esa caja parece sospechosamente bonita. Las cajas normales no posan así… los gatos sí, pero las cajas no.','¡Míralo! Es tan bonito que casi da pena cortarlo. Casi. Tampoco exageremos: sigue siendo pastel.','Pero antes de discutir quién recibirá la rebanada más grande… algo acaba de moverse detrás de nosotros.','¡Pero bueno! Parece que no estábamos solos. Tenemos público… y viene vestido para la ocasión.','¡Miau, miaui, miau-miau!','Dicen: “Llegamos temprano”. Lo cual es una traducción muy generosa para un grupo que apareció después del pastel.','¡Miauuu… miau, miau!','Ahora aseguran que sólo vinieron a felicitarte y que nadie ha pensado en robar crema del pastel. Nadie les preguntó eso.','¡Miaui! ¡Miau-miau-miaui!','Los gatos dicen que la vela apareció gracias a su impecable trabajo en equipo. Tú y yo sabemos quién reventó los globos, pero dejémoslos celebrar.');
lines[21]='La pregunta importante es quién recibirá la rebanada más grande. Como narrador imparcial, propongo que sea quien cumple años… y que los demás no arañen el mobiliario.';
