function buildCuteShapes(){if(celebrationFx.querySelector('.cute-shape'))return;const shapes=['♥','★','✦','♡','✿','🐾'],colors=['#ef6262','#68c7e8','#ffd45c','#83cc78','#f39bc8'];for(let i=0;i<16;i++){const shape=document.createElement('i');shape.className='cute-shape';shape.textContent=shapes[i%shapes.length];shape.style.setProperty('--x',`${5+Math.random()*90}%`);shape.style.setProperty('--y',`${12+Math.random()*72}%`);shape.style.setProperty('--color',colors[i%colors.length]);shape.style.setProperty('--size',`${11+Math.random()*13}px`);shape.style.setProperty('--speed',`${2.5+Math.random()*2.8}s`);shape.style.setProperty('--delay',`${-Math.random()*4}s`);celebrationFx.appendChild(shape)}}
