function updateRoomPerspective(dt){const wide=cameraMode==='room-wide',birthday=cameraMode==='birthday-page',tilt=roomLit?(birthday?.4:wide?.54:.42):0,targetY=roomLit?(birthday?-1.25:wide?-.68:-.42):-.5;presentStage.rotation.x+=(tilt-presentStage.rotation.x)*Math.min(1,dt*2.4);presentStage.position.y+=(targetY-presentStage.position.y)*Math.min(1,dt*2.2);roomBackdrop.material.opacity+=((roomLit?1:0)-roomBackdrop.material.opacity)*Math.min(1,dt*2)}
function updateGiftLid(now){if(!giftLid||!giftLidStart||!giftModel?.userData.opening)return;const progress=THREE.MathUtils.clamp((now-burstStarted)/620,0,1),ease=1-Math.pow(1-progress,3);giftLid.position.copy(giftLidStart.position);giftLid.position.y+=ease*.65;giftLid.position.x+=ease*.28;giftLid.rotation.copy(giftLidStart.rotation);giftLid.rotation.z-=ease*1.15}
function updateCandle(dt){const dark=['candle-lit','candle-blow','candle-out','candle-silence'].includes(phase),emotional=phase==='emotional',targetLight=dark?.018:emotional?.34:2.4,ease=Math.min(1,dt*(emotional?1.15:2.1));roomFill.intensity+=(targetLight-roomFill.intensity)*ease;roomBackdrop.material.color.lerp(dark?darkBackdropColor:emotional?emotionalBackdropColor:normalBackdropColor,ease);if(flame.visible){const time=performance.now()*.001,wave=Math.sin(time*13)*.1+Math.sin(time*21)*.045;flame.scale.set(.72+wave*.25,1.35+wave,.72-wave*.12);flame.position.x=Math.sin(time*17)*.012;flame.rotation.z=Math.sin(time*11)*.13;flameCore.scale.y=1.4+Math.sin(time*18)*.12;candleLight.intensity=3.8+Math.sin(time*16)*.55}if(phase==='candle-blow'&&micAnalyser&&micSamples){micAnalyser.getByteTimeDomainData(micSamples);let energy=0;for(const value of micSamples){const sample=(value-128)/128;energy+=sample*sample}const rms=Math.sqrt(energy/micSamples.length);blowFrames=rms>.105?blowFrames+1:Math.max(0,blowFrames-2);if(blowFrames>7)extinguishCandle()}}
function updatePageSceneFade(dt){if(phase!=='next-page'&&phase!=='page-turn'&&phase!=='birthday-page')return;const target=phase==='next-page'?1-pageTurnAmount:phase==='page-turn'?0:1;pageSceneOpacity+=(target-pageSceneOpacity)*Math.min(1,dt*(target>pageSceneOpacity?2.1:5));[decorations,presentStage].forEach(group=>group.traverse(object=>{if(!object.material)return;const materials=Array.isArray(object.material)?object.material:[object.material];materials.forEach(material=>{material.transparent=true;material.opacity=pageSceneOpacity})}))}
function updateCatConversation(){if(dialogue.hidden||!guests.visible)return;const catsTalking=narratorLabel.textContent==='GATITOS',translation=[24,26,28].includes(dialogueIndex);if(!catsTalking&&!translation)return;const time=performance.now()*.001;guests.children.forEach((cat,index)=>{const wave=Math.max(0,Math.sin(time*(catsTalking?5.2:3.2)-index*.62)),chosen=translation?index%7===dialogueIndex%7:1;if(!chosen)return;cat.position.y+=wave*(catsTalking?.075:.035);cat.rotation.z+=Math.sin(time*6-index*.7)*(catsTalking?.045:.018)})}
function updateNarrativeCamera(dt){if(!roomLit)return;updateCandle(dt);updatePageSceneFade(dt);updateCatConversation();const pageTarget=-Math.PI*.97*pageTurnAmount;storyPageHinge.rotation.y+=(pageTarget-storyPageHinge.rotation.y)*Math.min(1,dt*7);const wide=cameraMode==='room-wide',birthday=cameraMode==='birthday-page',targetScale=birthday?.54:wide?.48:.86;presentStage.scale.lerp(new THREE.Vector3(targetScale,targetScale,targetScale),Math.min(1,dt*3.2));camera.position.set(1.67,.25,10.25);camera.fov=34;camera.updateProjectionMatrix();camera.lookAt(1.67,.25,0)}
function updateGuests(dt){if(phase==='guests')guests.visible=true;updateDecorations(dt);if(!guests.visible)return;guestReveal=Math.min(1,guestReveal+dt*.7);const time=performance.now()*.001;guests.children.forEach((person,i)=>{const local=THREE.MathUtils.clamp((guestReveal-person.userData.delay)*2.2,0,1),eased=1-Math.pow(1-local,3),pulse=1+Math.sin(time*2.4+i*.9)*.025,bounce=person.userData.pose===1?Math.max(0,Math.sin(time*3+i))*.08:0;person.scale.setScalar(person.userData.baseScale*eased*pulse);person.position.y=person.userData.baseY+bounce;person.rotation.z=person.userData.baseRotationZ+Math.sin(time*1.8+i)*.025;person.traverse(part=>{if(part.isMesh){part.material.clippingPlanes=null;part.material.depthTest=true;part.material.opacity=eased;part.visible=true}})})}
function updateDecorations(dt){const active=phase==='guests'||phase.startsWith('balloon')||phase==='candle-found';if(!active)return;decorations.visible=true;decorationReveal=Math.min(1,decorationReveal+dt*.62);const eased=1-Math.pow(1-decorationReveal,3),total=Math.max(1,decorations.children.length-2),float=Math.sin(performance.now()*.00075)*.045,targetSpread=phase==='balloon-game'?1:0;balloonSpread+=(targetSpread-balloonSpread)*Math.min(1,dt*2.8);decorations.position.y=THREE.MathUtils.lerp(-2.3,.18,eased)+float*eased;balloonAssemblies.forEach(assembly=>{const rest=assembly.parts[0].userData.restPosition,offset=assembly.scatterTarget.clone().sub(rest).multiplyScalar(balloonSpread);assembly.parts.forEach(part=>part.position.copy(part.userData.restPosition).add(offset))});const correct=balloonAssemblies[candleAssembly]?.parts[0],remainingBlockers=candleBlockers.filter(index=>!balloonAssemblies[index].popped).length;if(correct){candleShadow.position.copy(correct.position);candleShadow.position.z+=.22;const shadowScale=phase==='balloon-game'&&!balloonAssemblies[candleAssembly].popped&&remainingBlockers<=2?1:0;candleShadow.scale.lerp(new THREE.Vector3(shadowScale,shadowScale,shadowScale),Math.min(1,dt*7))}decorations.children.forEach((part,i)=>{if(!part.material)return;const opacity=THREE.MathUtils.clamp((decorationReveal-(i/total)*.13)*2.5,0,1);part.material.opacity=opacity;part.material.transparent=true;part.material.depthTest=false;part.material.depthWrite=false;part.renderOrder=60;if(part.geometry?.type==='SphereGeometry')part.rotation.z=Math.sin(performance.now()*.00125+i)*.045});for(let i=balloonBursts.length-1;i>=0;i--){const burst=balloonBursts[i];burst.age+=dt;burst.particles.forEach(piece=>{piece.userData.velocity.y-=dt*1.6;piece.position.addScaledVector(piece.userData.velocity,dt);piece.rotation.x+=dt*8;piece.material.depthTest=false;piece.renderOrder=70;piece.material.opacity=Math.max(0,1-burst.age/1.05)});if(burst.age>1.05){decorations.remove(burst.group);balloonBursts.splice(i,1)}}}
function positionGiftHint(){if(giftHint.hidden||phase!=='gift')return;const point=presentStage.localToWorld(new THREE.Vector3(0,1.62,.25)).project(camera);giftHint.style.left=`${(point.x*.5+.5)*innerWidth}px`;giftHint.style.top=`${(-point.y*.5+.5)*innerHeight}px`;giftHint.style.bottom='auto'}
function updateCelebration(now,dt){if(tableModel&&roomLit){tableModel.visible=true;tableModel.traverse(object=>{if(object.material)object.material.opacity+=(1-object.material.opacity)*Math.min(1,dt*2.4)})}const giftOpeningVisible=phase==='gift-opening'&&now-burstStarted<420;if(giftModel&&roomLit&&(phase!=='cake'&&phase!=='gift-opening'||giftOpeningVisible)){giftModel.visible=true;const jumpAge=(now-giftJumpStarted)/1000,jump=jumpAge<.55?Math.sin(jumpAge/.55*Math.PI)*(.22+giftTaps*.045):0,anticipation=phase==='gift'&&giftTaps?Math.sin(now*.018)*giftTaps*.012:0;giftModel.position.y=jump+Math.abs(anticipation);giftModel.rotation.y=Math.sin(now*.006)*(.025+giftTaps*.012);giftModel.rotation.z=anticipation*.35;giftModel.traverse(object=>{if(object.material)object.material.opacity+=(1-object.material.opacity)*Math.min(1,dt*4)})}if(cakeModel&&cakeModel.visible){const target=cakeModel.userData.targetScale||1,cakeScale=THREE.MathUtils.lerp(cakeModel.scale.x,target,Math.min(1,dt*3));cakeModel.scale.setScalar(cakeScale);cakeModel.rotation.y+=dt*.32;cakeModel.traverse(object=>{if(object.material)object.material.opacity+=(1-object.material.opacity)*Math.min(1,dt*2.5)})}if(!burstStarted)return;const age=(now-burstStarted)/1000;celebrationDust.forEach((particle,i)=>{if(!particle.visible)return;particle.userData.velocity.y-=dt*2.1;particle.position.addScaledVector(particle.userData.velocity,dt);particle.rotation.x+=dt*(2+i%4);particle.material.opacity=Math.max(0,age<.65?.95:1-(age-.65)/.9);particle.scale.multiplyScalar(1+dt*.5);if(particle.material.opacity<=0)particle.visible=false})}
function animate(now){requestAnimationFrame(animate);const dt=Math.min((now-last)/1000,.05);last=now;const target=-Math.PI*.97*openAmount;hinge.rotation.y+=((target||-.025)-hinge.rotation.y)*Math.min(1,dt*7);const opened=phase!=='opening'&&phase!=='intro';camera.position.x+=(1.67-camera.position.x)*Math.min(1,dt*8);camera.position.y+=((roomLit?1.45:.25)-camera.position.y)*Math.min(1,dt*2.2);camera.position.z+=((opened?10.25:11)-camera.position.z)*Math.min(1,dt*3);camera.lookAt(1.67,roomLit?-.35:.25,0);left.material.opacity=1;left.material.transparent=false;border.material.opacity=.65;emblem.visible=true;if(roomLit)contentReveal=Math.max(0,contentReveal-dt*1.8);else if(revealReady)contentReveal=Math.min(1,contentReveal+dt*1.25);chain.traverse(object=>{if(object.material)object.material.opacity=contentReveal});const chainLightTarget=roomLit?0:phase==='chain'?48:phase==='dialogue'?16:0;chainLight.intensity+=(chainLightTarget-chainLight.intensity)*Math.min(1,dt*3);chain.position.y=2.48;chainSwing*=Math.pow(.91,dt*60);links.forEach((bead,i)=>{const ratio=i/(links.length-1),wave=Math.sin(ratio*Math.PI)*chainSwing+Math.sin(now*.006-i*.42)*(.018+pullAmount*.035)*ratio;bead.position.x+=(wave-bead.position.x)*Math.min(1,dt*(10+i*.12));bead.position.y=-i*.135-pullAmount*1.42*ratio});const tail=links[links.length-1];handle.position.x+=(tail.position.x-handle.position.x)*Math.min(1,dt*14);handle.position.y=-3.18-pullAmount*1.42;handle.rotation.z+=(chainSwing*.65-handle.rotation.z)*Math.min(1,dt*10);card.rotation.y=Math.sin(now*.00035)*.018*(1-openAmount);dust.forEach((p,i)=>{p.position.y+=dt*(.035+(i%5)*.007);p.position.x+=Math.sin(now*.0005+i)*dt*.018;if(p.position.y>5)p.position.y=-5});updateRoomPerspective(dt);updateGiftLid(now);updateCelebration(now,dt);if(giftModel?.userData.opened)giftModel.visible=false;updateGuests(dt);updateNarrativeCamera(dt);positionGiftHint();renderer.render(scene,camera)}requestAnimationFrame(animate);
